const found=new Set();let toastTimer;const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function toast(message){const t=document.getElementById('play-toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3000)}
function discover(){}
function burst(x,y){if(reducedMotion.matches)return;for(let i=0;i<28;i++){const piece=document.createElement('span');piece.className='confetti-piece';piece.style.setProperty('--x',x+'px');piece.style.setProperty('--y',y+'px');piece.style.setProperty('--dx',(Math.random()-.5)*420+'px');piece.style.setProperty('--dy',(-40-Math.random()*280)+'px');piece.style.setProperty('--spin',Math.random()*600+'deg');piece.style.setProperty('--c',['#2954d8','#89b4ff','#f6db6d','#c3d5ff'][i%4]);document.body.append(piece);setTimeout(()=>piece.remove(),1000)}}
document.querySelector('.spark-button').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();burst(r.x+r.width/2,r.y+r.height/2);toast('A small celebration. Just because. ✳')});
document.querySelectorAll('[data-desk]').forEach(b=>b.addEventListener('click',()=>discover('notebook')));
document.getElementById('sticky-reveal').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',!open);document.getElementById('sticky-secret').hidden=open;if(!open)discover('note')});
const flipNote=document.getElementById('flip-note');flipNote.addEventListener('click',()=>{const back=flipNote.getAttribute('aria-expanded')!=='true';flipNote.setAttribute('aria-expanded',back);document.getElementById('personal-note-copy').innerHTML=back?'Current chapter:<br><b>Less guessing.<br>More evidence.<br>Keep learning.</b><small>tap to turn back ↻</small>':'Things I believe:<br><b>“I don’t know yet”<br>is a good place<br>to start.</b><small>tap to turn over ↻</small>';discover('note')});
document.querySelectorAll('[data-open-project]').forEach(b=>b.addEventListener('click',()=>{document.querySelector(`[data-project="${b.dataset.openProject}"]`).click();discover('folder')}));
document.querySelectorAll('.project').forEach(p=>{const visual=p.querySelector('.project-visual');const button=p.querySelector('[data-project]');visual.removeAttribute('aria-hidden');visual.setAttribute('role','button');visual.setAttribute('tabindex','0');visual.setAttribute('aria-label',`Open project: ${p.querySelector('h3').textContent}`);visual.addEventListener('click',()=>button.click());visual.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();button.click()}})});
document.querySelectorAll('[data-reveal]').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);document.getElementById('reveal-'+b.dataset.reveal).hidden=!open;if(open)discover('story')}));
const skillNotes=["Network and wireless tools I\u2019ve used as part of my cybersecurity learning.", "Tools I\u2019ve used while exploring vulnerability assessment, web security, and exploitation concepts.", "Reconnaissance tools I\u2019ve used to explore information gathering.", "Password-auditing tools I\u2019ve used in my cybersecurity learning.", "My Autopsy work includes examining artefacts and documenting observations.", "Tools I use in coursework and projects, including the Docker-based MongoDB access-control lab."];document.querySelectorAll('.skill-list>div').forEach((row,i)=>{const heading=row.querySelector('h3');const title=heading.textContent;heading.textContent='';const b=document.createElement('button');b.className='skill-toggle';b.setAttribute('aria-expanded','false');b.innerHTML=title+'<span>＋</span>';heading.append(b);const extra=document.createElement('div');extra.className='skill-extra';extra.hidden=true;extra.textContent=skillNotes[i];row.append(extra);row.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);extra.hidden=!open;b.querySelector('span').textContent=open?'−':'＋'})});
const credentialNotes=['The certification I use as a foundation for continued cybersecurity learning.','A completed professional certificate covering security foundations and practical analyst skills.','A completed Cisco learning path supporting my exploration of junior analyst roles.'];document.querySelectorAll('.credentials article').forEach((card,i)=>{const b=document.createElement('button');b.className='credential-extra-button';b.textContent='a little context ↗';b.setAttribute('aria-expanded','false');const p=document.createElement('div');p.className='credential-extra';p.hidden=true;p.textContent=credentialNotes[i];card.append(b,p);b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',open);p.hidden=!open;b.textContent=open?'close note ↙':'a little context ↗'})});
const board=document.getElementById('play-board');const movable=[...document.querySelectorAll('.desk-object')];function moveObject(obj,x,y){const boardRect=board.getBoundingClientRect();const width=obj.offsetWidth,height=obj.offsetHeight;const baseX=obj.offsetLeft,baseY=obj.offsetTop;const dx=Math.min(boardRect.width-width-baseX-12,Math.max(12-baseX,x));const dy=Math.min(boardRect.height-height-baseY-40,Math.max(45-baseY,y));obj.dataset.x=dx;obj.dataset.y=dy;obj.style.setProperty('--drag-x',dx+'px');obj.style.setProperty('--drag-y',dy+'px')}
movable.forEach(obj=>{const handle=obj.querySelector('.drag-handle');let pointer=null;handle.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY,dx:Number(obj.dataset.x||0),dy:Number(obj.dataset.y||0)};handle.setPointerCapture(e.pointerId);obj.classList.add('is-dragging')});handle.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;moveObject(obj,pointer.dx+e.clientX-pointer.x,pointer.dy+e.clientY-pointer.y)});const end=()=>{pointer=null;obj.classList.remove('is-dragging')};handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);handle.addEventListener('lostpointercapture',end);handle.addEventListener('keydown',e=>{const dir={ArrowLeft:[-12,0],ArrowRight:[12,0],ArrowUp:[0,-12],ArrowDown:[0,12]}[e.key];if(dir){e.preventDefault();moveObject(obj,Number(obj.dataset.x||0)+dir[0],Number(obj.dataset.y||0)+dir[1])}})});
function resetDesk(){movable.forEach(obj=>{obj.dataset.x=0;obj.dataset.y=0;obj.style.setProperty('--drag-x','0px');obj.style.setProperty('--drag-y','0px')})}document.getElementById('tidy-desk').onclick=()=>{resetDesk();toast('Everything back in its very specific mess. ↺')};window.addEventListener('resize',resetDesk);
